return array('domain'=>'flx-updater-manager','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'en_US','messages'=>array('Yönet'=>'Manage','Güncelleme sunucusunu WordPress panelinden yönetir'=>'Manages the update server from the WordPress admin','Kaydedildi.'=>'Saved.','Anahtar üretildi. Güvenlik için burada gösterilmez: 5 dakika içinde Updater › Siteler ekranını açın, anahtar orada bir kez görünür.'=>'Key created. For security it is not shown here: open Updater › Sites within 5 minutes, the key is shown there once.','Site bulunamadı. Önce anahtarlı siteleri listeleyin.'=>'Site not found. List the keyed sites first.','Güncelleme sunucusunun istatistikleri, siteleri, paketleri ve güvenlik ayarları.'=>'Update server statistics, sites, packages and security settings.','Sunucu genel bakış'=>'Server overview','Bağlanan siteler'=>'Connected sites','Anahtarlı siteler'=>'Keyed sites','Sunucudaki paketler'=>'Server packages','Sunucu güvenliği'=>'Server security','Sunucu kaynakları'=>'Server resources','Site anahtarını test et'=>'Test site key','Site ekle (anahtar üret)'=>'Add site (create key)','Site erişimini düzenle'=>'Edit site access','Siteyi aktif/pasif yap'=>'Turn site on/off','Siteyi sil'=>'Delete site','Bağlanan siteye anahtar ver'=>'Issue key to connected site','Acil durdurma / anahtarsız dağıtım'=>'Emergency stop / keyless distribution','Ülke erişimi'=>'Country access','Herkese açık paketler'=>'Public packages','Paketleri yeniden oku'=>'Reload packages','Zip saklama'=>'Zip retention','Değişiklik yok.'=>'No changes.','Ülke veritabanını güncelle'=>'Update country database','Genel bakış'=>'Overview','Ülkeler'=>'Countries','Siteler'=>'Sites','Paketler'=>'Packages','Güvenlik'=>'Security','Kaynaklar'=>'Resources','Bağlantı'=>'Connection','Updater Manager'=>'Updater Manager','Updater'=>'Updater','Site'=>'Site','Kontrol'=>'Checks','İndirme'=>'Downloads','Kopyalandı'=>'Copied','Kaldır'=>'Remove','Depo ekle…'=>'Add repository…','Depo seçin'=>'Pick a repository','Yükleniyor…'=>'Loading…','Liste alınamadı'=>'Could not load the list','Enter ile ekleyin'=>'Press Enter to add','Listeyi yenile'=>'Refresh list','Sunucuda yapılıyor…'=>'Working on the server…','Bu işlem için yetkiniz yok.'=>'You are not allowed to do this.','Yönetici anahtarı bu siteden silindi. Sunucudaki anahtar duruyor; sunucu panelinden silebilirsiniz.'=>'Manager key removed from this site. The key still exists on the server; you can delete it in the server panel.','Yönetici anahtarı "flxm_" ile başlar ve 53 karakterdir. Sunucu panelinde Updater Manager kartından üretin.'=>'A manager key starts with "flxm_" and is 53 characters long. Generate one in the Updater Manager card of the server panel.','Bağlandı: Flux Update Server %1$s, anahtar "%2$s".'=>'Connected: Flux Update Server %1$s, key "%2$s".','Yönetici anahtarı girilmemiş.'=>'No manager key entered.','Sunucu adresi geçersiz.'=>'Invalid server address.','Sunucuya ulaşılamadı: %s'=>'Could not reach the server: %s','Bu sunucuda yönetici API\'si yok. Güncelleme sunucusunu 1.12.0 ya da üstüne yükseltin.'=>'This server has no admin API. Upgrade the update server to 1.12.0 or later.','Sunucudan beklenmeyen yanıt (HTTP %d).'=>'Unexpected response from the server (HTTP %d).','Yönetici anahtarı geçersiz ya da sunucuda silinmiş.'=>'The manager key is invalid or was deleted on the server.','Sunucu hatası.'=>'Server error.','Önceki eşit döneme göre'=>'Compared with the previous period of the same length','FluxWP güncelleme sunucusunu buradan yönetin: istatistikler, siteler, anahtarlar, paketler ve güvenlik.'=>'Manage the FluxWP update server from here: statistics, sites, keys, packages and security.','%1$s · Flux Update Server %2$s'=>'%1$s · Flux Update Server %2$s','Sunucu paneli'=>'Server panel','Bölümler'=>'Sections','Acil durdurma açık.'=>'Emergency stop is on.','Hiçbir siteye güncelleme, paket ya da uygulama dağıtılmıyor (503).'=>'No updates, packages or apps are served to any site (503).','Anahtarsız dağıtım kapalı.'=>'Keyless distribution is off.','Yalnız aktif site anahtarı olan siteler paket alıyor.'=>'Only sites with an active site key receive packages.','Yeni site anahtarı: %s'=>'New site key: %s','Site bu anahtarı bir sonraki güncelleme kontrolünde kendiliğinden alır (7 gün içinde; hemen almak için sitede FluxWP Panel › Ayarlar › "Bağlantıyı test et"). Elle girmeniz gerekmez. Şimdi Siteler sekmesinden erişimini seçin; seçene kadar site yalnız public paketleri görür.'=>'The site picks up this key on its next update check (within 7 days; to get it now, use FluxWP Panel › Settings › "Test connection" on the site). No need to enter it by hand. Now choose its access on the Sites tab; until then the site only sees public packages.','Bu anahtar bir daha gösterilmez. Şimdi kopyalayın ve sitenin FluxWP Panel › Ayarlar ekranında "Site anahtarı" alanına yapıştırın.'=>'This key will not be shown again. Copy it now and paste it into the "Site key" field under FluxWP Panel › Settings on the site.','Kopyala'=>'Copy','Geçerli bir IP adresi girin.'=>'Enter a valid IP address.','Bulunamadı'=>'Not found','Anahtar testi'=>'Key test','Geçersiz'=>'Invalid','Pasif'=>'Disabled','Geçerli'=>'Valid','Beta dahil'=>'Beta included','Kararlı'=>'Stable','Görebileceği paketler (%d):'=>'Packages it can see (%d):','Site en son %s bağlandı.'=>'The site last connected %s.','Site henüz bağlanmadı.'=>'The site has not connected yet.','%d gün'=>'%d days','Aktif site'=>'Active sites','Önceki dönem: %s'=>'Previous period: %s','Anahtarlı'=>'Keyed','%s site anahtarsız (public)'=>'%s sites without a key (public)','Kontrol isteği'=>'Update checks','%s anahtarsız'=>'%s without a key','Aktarılan'=>'Transferred','Zip indirmeleri'=>'Zip downloads','Ülke'=>'Country','%s sitenin ülkesi bilinmiyor'=>'%s sites with unknown country','İstekten, IP saklanmadan'=>'From the request, IPs not stored','Günlük kullanım'=>'Daily usage','Tekil site'=>'Unique sites','Bu aralıkta kayıt yok.'=>'No records in this range.','Paket'=>'Package','Kurulu site'=>'Installed on','Az'=>'Fewer','Çok'=>'More','%s site'=>'%s sites','%1$s site bu aralıkta, toplam %2$s kayıtlı'=>'%1$s sites in this range, %2$s recorded in total','Bu aralıkta güncelleme denetleyen site yok.'=>'No site checked for updates in this range.','Erişim'=>'Access','Ortam'=>'Environment','İstek'=>'Requests','Son'=>'Last','Adres bildirmedi'=>'No address sent','Tümünü göster (%s)'=>'Show all (%s)','Zorunlu kayıt yalnız site adresi ve ülkedir. IP saklanmaz: ülke, istek anında IP\'den bulunur ve yalnız ülke kodu tutulur. WordPress/PHP sürümü yalnız kullanım verisi izniyle.'=>'Only the site address and country are recorded by default. IPs are not stored: the country is looked up from the IP while the request is handled and only the country code is kept. WordPress/PHP versions only with the usage-data opt-in.','Teslim bekliyor'=>'Waiting for pickup','FluxWP Panel gerekli'=>'FluxWP Panel needed','Anahtar ver'=>'Issue key','Ülke trafiği'=>'Traffic by country','%1$s ülke · %2$s engellenen istek'=>'%1$s countries · %2$s blocked requests','Ülke veritabanı yok'=>'No country database','Cloudflare arkasında değilseniz ülkeler bilinmiyor görünür.'=>'Unless you are behind Cloudflare, countries show as unknown.','Veritabanını indir'=>'Download the database','Veri'=>'Data','Engellenen'=>'Blocked','En çok inen'=>'Most downloaded','Kontrol ve indirmeler her istekte sayılır; kullanım verisi izni gerekmez. Satıra tıklayınca o ülkedeki paketler açılır.'=>'Checks and downloads are counted on every request; no usage-data opt-in needed. Click a row to see that country\'s packages.','Private erişim'=>'Private access','(public paketler her siteye açık)'=>'(public packages are open to every site)','Tüm private paketler (yeni eklenenler dahil)'=>'All private packages (including new ones)','Seçilen depolar ve paketler'=>'Selected repositories and packages','Private depo yok.'=>'No private repositories.','tümü, %d paket + sonradan eklenenler'=>'all, %d packages + ones added later','Tüm private paketler'=>'All private packages','(tümü)'=>'(all)','Yalnız public paketler'=>'Public packages only','Site ekle'=>'Add site','Site adı'=>'Site name','ör. Örnek Site'=>'e.g. Example Site','Kanal'=>'Channel','Kararlı sürümler'=>'Stable releases','Anahtar üret'=>'Generate key','Var olan bir anahtarı test et'=>'Test an existing key','Anahtarın hangi siteye ait olduğunu ve hangi paketleri görebildiğini gösterir.'=>'Shows which site the key belongs to and which packages it can see.','Test et'=>'Test','Henüz site yok. "Site ekle" ile ilk anahtarı üretin.'=>'No sites yet. Generate the first key with "Add site".','Durum'=>'Status','Kurulu paketler'=>'Installed packages','İzin'=>'Permissions','Teslim süresi doldu'=>'Pickup expired','Hiç bağlanmadı'=>'Never connected','%d gündür yok'=>'Missing for %d days','Bağlı'=>'Connected','Pasif yap'=>'Disable','Aktif yap'=>'Enable','Erişimi düzenle'=>'Edit access','Ad'=>'Name','Kaydet'=>'Save','Bu site silinsin mi? Anahtarı hemen geçersiz olur.'=>'Delete this site? Its key stops working at once.','Sunucu dosyasından (config.php)'=>'From the server file (config.php)','Sunucu anahtarın yalnız özetini (sha256) saklar. Kaybolan anahtar geri alınamaz: siteyi silip yeni anahtar üretin. Anahtarsız bağlanan bir siteye Genel bakış › Bağlanan siteler › "Anahtar ver" ile de anahtar verebilirsiniz.'=>'The server stores only the key\'s hash (sha256). A lost key cannot be recovered: delete the site and generate a new key. You can also give a key to a site that connected without one under Overview › Connected sites › "Issue key".','Paket yok. GitHub sekmesinde depoları ve (private depo için) token\'ı girin; depoda release yoksa bir pakete sürüm çıkın.'=>'No packages. Enter the repositories (and a token for private ones) on the GitHub tab; if a repository has no releases, release a package.','Tür'=>'Type','Son sürüm'=>'Latest version','Boyut'=>'Size','Yayın'=>'Published','Anahtarla'=>'With key','Tema'=>'Theme','Eklenti'=>'Plugin','Yeni sürüm en geç 5 dakikada görünür; webhook ayarlıysa hemen. Private depodaki bir paketi anahtarsız açmak için GitHub sekmesinde "Herkese açık paketler"i işaretleyin.'=>'New versions show up within 5 minutes, at once with the webhook. To serve a package from a private repository without a key, tick it under "Public packages" on the GitHub tab.','Bağlı değil'=>'Not connected','%1$d paket okundu (%2$d private, %3$d public)'=>'%1$d packages read (%2$d private, %3$d public)','Token yok: yalnız public depolar okunuyor.'=>'No token: only public repositories are read.','Okunamadı'=>'Unreadable','Private depolar'=>'Private repositories','(paketleri yalnız site anahtarıyla)'=>'(packages only with a site key)','Public depolar'=>'Public repositories','(paketleri herkese anahtarsız; boşsa public güncelleme kapalı)'=>'(packages for everyone without a key; empty turns public updates off)','(private depodaki bu paketler anahtarsız iner; ör. web sitesindeki indirme butonu için flx-setup)'=>'(these packages from private repositories download without a key; e.g. flx-setup for a website download button)','Uygulama deposu'=>'App repository','(masaüstü/mobil uygulama, tag v<sürüm>)'=>'(desktop/mobile app, tag v<version>)','FluxWP masaüstü deposu'=>'FluxWP desktop repository','(fluxapp-v<sürüm> yayınları; boşsa ilk private depo)'=>'(fluxapp-v<version> releases; empty uses the first private repository)','Liste GitHub\'dan gelir: token\'ın erişebildiği depolar ve bu sahiplerin public depoları. Listede olmayanı owner/repo yazıp Enter ile ekleyin.'=>'The list comes from GitHub: repositories the token can reach and public repositories of the same owners. Type owner/repo and press Enter to add one that is not listed.','(fine-grained, private depolar + uygulama deposu, Contents: Read-only)'=>'(fine-grained, private repositories + app repository, Contents: Read-only)','Kayıtlı: …%s (değiştirmek için yenisini yazın)'=>'Saved: …%s (type a new one to change it)','Token yalnız güncelleme sunucusunda saklanır; bu siteye geri okunmaz.'=>'The token is stored only on the update server; it is never read back to this site.','Kaydet ve test et'=>'Save and test','Anında yayın (isteğe bağlı)'=>'Instant publish (optional)','Yeni sürüm en geç 5 dakikada görünür. Anında görünsün isterseniz bu secret\'ı paket deposunun Settings › Secrets › Actions bölümüne <code>UPDATE_WEBHOOK_SECRET</code> adıyla ekleyin; repo değişkeni <code>UPDATE_SERVER</code> = <code>%s</code>.'=>'New versions show up within 5 minutes. To make them show up at once, add this secret to the package repository under Settings › Secrets › Actions as <code>UPDATE_WEBHOOK_SECRET</code>; repository variable <code>UPDATE_SERVER</code> = <code>%s</code>.','Yeni secret üretilsin mi? Eskisi hemen çalışmaz; GitHub\'daki secret\'ı da değiştirmeniz gerekir.'=>'Generate a new secret? The old one stops working at once; you must change the secret on GitHub too.','Secret üret'=>'Generate secret','Yeni secret üret'=>'Generate new secret','Dağıtım anahtarları'=>'Distribution switches','Acil durdurma'=>'Emergency stop','Durduruldu'=>'Stopped','Dağıtım açık'=>'Distribution on','Tüm güncelleme kontrolleri, paket ve uygulama indirmeleri 503 ile durur (anahtarlı siteler dahil). Sunucu paneli, webhook ve bu ekran çalışmaya devam eder.'=>'All update checks, package and app downloads stop with 503 (keyed sites included). The server panel, the webhook and this screen keep working.','Dağıtım yeniden açılsın mı?'=>'Turn distribution back on?','Tüm dağıtım durdurulsun mu? Hiçbir site güncelleme alamaz.'=>'Stop all distribution? No site can get updates.','Dağıtımı aç'=>'Turn distribution on','Tümünü durdur'=>'Stop everything','Anahtarsız dağıtım'=>'Keyless distribution','Kapalı'=>'Off','Açık'=>'On','Public depo yok'=>'No public repository','Kapatınca anahtarsız ve pasif anahtarlı istekler (public paketler, latest.zip indirme butonu, masaüstü/mobil uygulama) 401 alır. Aktif anahtarlı siteler etkilenmez.'=>'When off, keyless requests and disabled keys (public packages, the latest.zip download button, desktop/mobile app) get 401. Sites with an active key are not affected.','Anahtarsız dağıtım yeniden açılsın mı?'=>'Turn keyless distribution back on?','Anahtarsız dağıtım kapatılsın mı? Anahtarı olmayan siteler ve uygulamalar güncelleme alamaz.'=>'Turn keyless distribution off? Sites and apps without a key will not get updates.','Anahtarsız dağıtımı aç'=>'Turn keyless distribution on','Anahtarsızları kapat'=>'Turn keyless off','Her değişiklik sunucunun erişim günlüğüne yönetici anahtarının adıyla yazılır.'=>'Every change is written to the server\'s access log with the manager key\'s name.','Ülke veritabanı'=>'Country database','Kurulu'=>'Installed','Kaynak'=>'Source','Veri tarihi'=>'Data date','İndirildi'=>'Downloaded','Yok'=>'None','İndirin ya da sunucu panelinden .mmdb dosyası yükleyin.'=>'Download it, or upload an .mmdb file in the server panel.','Son deneme başarısız'=>'Last attempt failed','Şimdi güncelle'=>'Update now','Ülke veritabanı silinsin mi?'=>'Delete the country database?','Sil'=>'Delete','Ülkesini bul'=>'Find country','IP harici bir servise gönderilmez; arama güncelleme sunucusunda yapılır. Veritabanı ayda bir kendiliğinden yenilenir.'=>'The IP is not sent to any outside service; the lookup runs on the update server. The database refreshes itself monthly.','Seçilen ülkeleri engelle'=>'Block selected countries','Yalnız seçilen ülkelere izin ver'=>'Allow only selected countries','Ülke ekle… (ad ya da TR gibi kod)'=>'Add country… (name or a code like TR)','Aktif anahtarlı siteler muaf (yalnız anahtarsız istekler kurala tabi)'=>'Sites with an active key are exempt (only keyless requests follow the rule)','Ülke veritabanını ayda bir kendiliğinden güncelle'=>'Update the country database monthly on its own','Engellenen istek 403 (region_blocked) alır ve yalnız ülke koduyla sayılır. Ülkesi bulunamayan istek "engelle" kipinde geçer, "yalnız izin ver" kipinde engellenir. Kural güncelleme kontrolü, paket ve uygulama indirmelerine uygulanır; panel ve bu ekran etkilenmez.'=>'A blocked request gets 403 (region_blocked) and is counted by country code only. A request with an unknown country passes in block mode and is blocked in allow mode. The rule applies to update checks, package and app downloads; the panel and this screen are not affected.','Zip dosyaları'=>'Zip files','GitHub önbelleği'=>'GitHub cache','İstatistik'=>'Statistics','Günlük'=>'Log','Ayarlar ve diğer'=>'Settings and other','Depolama'=>'Storage','Makine diski (paylaşımlı)'=>'Machine disk (shared)','%s boş'=>'%s free','Paylaşımlı hosting\'de PHP sunucudaki tüm hesapların ortak diskini görür; bu sizin kotanız değil.'=>'On shared hosting PHP sees the disk shared by every account on the machine; this is not your quota.','Disk'=>'Disk','Sunucu verisi (data/)'=>'Server data (data/)','Eski zipleri temizle'=>'Clean old zips','Erişim günlüğü silinsin mi?'=>'Delete the access log?','Günlüğü temizle'=>'Clear log','API kotası (saatlik)'=>'API quota (hourly)','Kullanılan %1$s · yenilenme %2$s'=>'Used %1$s · resets %2$s','Paket önbelleği'=>'Package cache','boş'=>'empty','Her %d dakikada bir GitHub\'dan yenilenir; webhook gelirse hemen.'=>'Refreshed from GitHub every %d minutes; at once when the webhook fires.','Sürüm'=>'Version','Bellek sınırı'=>'Memory limit','sınırsız'=>'unlimited','Süre sınırı'=>'Time limit','%d sn'=>'%d s','yok'=>'none','Sunucu yükü (1/5/15 dk)'=>'Server load (1/5/15 min)','intl (ülke adları)'=>'intl (country names)','var'=>'yes','Dosyalar'=>'Files','%1$d zip, %2$s'=>'%1$d zips, %2$s','Her paketin son sürümleri sunucuda saklanır. Daha eski bir sürüm istenirse GitHub release\'ten yeniden indirilir ve son indirmeden sonra belirtilen süre dolunca silinir. Temizlik saatte bir kendiliğinden yapılır.'=>'The latest versions of each package are kept on the server. An older version is fetched from the GitHub release again when asked for and deleted once the set time after its last download has passed. Cleanup runs every hour on its own.','Paket başına saklanan sürüm'=>'Versions kept per package','Eski sürüm kaç saat sonra silinsin'=>'Delete older versions after (hours)','Sunucu bağlantısı'=>'Server connection','Anahtar: %s'=>'Key: %s','Sunucu adresi'=>'Server address','Yönetici anahtarı'=>'Manager key','Kayıtlı (değiştirmek için yenisini yazın)'=>'Saved (type a new one to change it)','Anahtarı sunucu panelinde (/admin › Updater Manager) "Yönetici anahtarı üret" ile alın. Anahtar bu sitede şifreli saklanır ve bir daha gösterilmez.'=>'Get the key in the server panel (/admin › Updater Manager) with "Generate manager key". The key is stored encrypted on this site and is never shown again.','Kaydet ve bağlan'=>'Save and connect','Yönetici anahtarı bu siteden silinsin mi?'=>'Remove the manager key from this site?','Bağlantıyı kaldır'=>'Remove connection','wp-config.php\'de <code>FLXUM_SERVER</code> ve <code>FLXUM_KEY</code> sabitleri bu alanları ezer.'=>'The <code>FLXUM_SERVER</code> and <code>FLXUM_KEY</code> constants in wp-config.php override these fields.','Nasıl bağlanır?'=>'How to connect','Güncelleme sunucusunu 1.12.0 ya da üstüne yükseltin.'=>'Upgrade the update server to 1.12.0 or later.','Sunucu panelinde (/admin) en alttaki "Updater Manager" kartında bir ad yazıp "Yönetici anahtarı üret"e basın.'=>'In the server panel (/admin), type a name in the "Updater Manager" card at the bottom and press "Generate manager key".','Anahtarı (flxm_…) buraya yapıştırıp "Kaydet ve bağlan"a basın.'=>'Paste the key (flxm_…) here and press "Save and connect".','Anahtar sunucudaki tüm ayarlara ve istatistiklere erişir; yönetici anahtarı üretme ve ülke veritabanı dosyası yükleme sunucu panelinde kalır. Sunucu panelinden silinen anahtar hemen çalışmaz olur.'=>'The key reaches every setting and statistic on the server; creating manager keys and uploading the country database file stay in the server panel. A key deleted in the server panel stops working at once.','Yönetici anahtarları'=>'Manager keys','Bu site'=>'This site','Son kullanım: %s'=>'Last used: %s','Bu yönetici anahtarı silinsin mi?'=>'Delete this manager key?','Yeni anahtar yalnız sunucu panelinde üretilir. Bu sitenin anahtarını sunucu panelinden silebilirsiniz.'=>'New keys are generated only in the server panel. You can delete this site\'s key there.','Sunucu paneli parolası'=>'Server panel password','Yeni parola'=>'New password','Tekrar'=>'Repeat','Değiştir'=>'Change'));
